        if r == 0:
            desc.append(("v", c, "top", r, c))
        elif r == h - 1:
            desc.append(("v", c, "bottom", r, c))
        elif c == 0:
            desc.append(("h", r, "left", r, c))
        elif c == w - 1:
            desc.append(("h", r, "right", r, c))

    if not desc:
        return [row[:] for row in grid]

    def axis_cells(d):
        kind, axis, side, _, _ = d
        if kind == "v":
            return [(r, c) for r, c in sevens if c == axis]
        return [(r, c) for r, c in sevens if r == axis]

    # The marker whose line meets the most 7s controls the movement.
    active = max(desc, key=lambda d: (len(axis_cells(d)), -d[3], -d[4]))
    fixed = set()
    for d in desc:
        fixed.update(axis_cells(d))

    out = [[1] * w for _ in range(h)]

    def move_to_corner(cells, top, left):
        if not cells:
            return
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
