        k, a, side, mr, mc = d
        cells = axis_cells(d)
        if not cells:
            out[mr][mc] = 2
            continue
        if k == "v":
            if side == "top":
                rows = range(0, max(r for r, c in cells) + 1)
            else:
                rows = range(min(r for r, c in cells), h)
            for r in rows:
                if out[r][a] != 7:
                    out[r][a] = 2
        else:
            if side == "left":
